//! Final-gate MVCC races: no real browser, owner data, account or provider action.
async fn snapshot_form_stop_race(first_control:bool){
    let(mut c,context,packet)=browser_command_fixture().await;let memory=json!({"messages":[{"text":"Fictional retained message"}],"updated_at":"2026-11-15T00:00:00Z"});browser_save(&mut c,"agent_conversation:primary",memory.clone()).await;if !first_control{browser_save(&mut c,"naukri_automation",json!({"revision":1,"state":"RUNNING","policy":null})).await;}
    let mut owner=connection().await;let mut held=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *held).await.unwrap();let mut observing=connection().await;sqlx::query("SET application_name='fixture_form_snapshot_wait'").execute(&mut observing).await.unwrap();let observation=browser_form_observation(&packet);let application=packet["id"].clone();let task=tokio::spawn(async move{browser_form_native(&mut observing,"inspect_form",&context,json!({"application_id":application,"inspection":observation})).await});let mut waiting=false;
    for _ in 0..200{waiting=sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE application_name='fixture_form_snapshot_wait' AND wait_event_type='Lock')").fetch_one(&mut c).await.unwrap();if waiting{break;}tokio::time::sleep(std::time::Duration::from_millis(10)).await;}assert!(waiting,"fixture must establish its snapshot while waiting for the owner row");
    sqlx::query("INSERT INTO owner_preferences(key,value) VALUES('naukri_automation','{\"revision\":2,\"state\":\"STOPPED\",\"policy\":null}') ON CONFLICT(key) DO UPDATE SET value=excluded.value").execute(&mut *held).await.unwrap();
    if first_control{sqlx::query("UPDATE owner_preferences SET updated_at=clock_timestamp() WHERE key='agent_conversation:primary'").execute(&mut *held).await.unwrap();}
    held.commit().await.unwrap();assert_eq!(tokio::time::timeout(std::time::Duration::from_secs(3),task).await.unwrap().unwrap().unwrap_err(),Failure("browser_profile_database_error"));assert_eq!(browser_pref(&mut c,"agent_conversation:primary").await,memory);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'fill_plan:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn browser_snapshot_existing_stop_without_lock_row_touch_is_rejected_by_authority_version_lock(){snapshot_form_stop_race(false).await;}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn browser_snapshot_first_stop_invisible_to_old_snapshot_is_rejected_by_lock_row_version(){snapshot_form_stop_race(true).await;}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn browser_and_queue_lock_versions_advance_without_rewriting_memory_or_message_ttl(){
    let(mut c,context,_)=browser_command_fixture().await;let memory=json!({"messages":[{"text":"Fictional retained message"}],"updated_at":"2026-11-15T00:00:00Z","request_ids":["fictional-existing-id"]});browser_save(&mut c,"agent_conversation:primary",memory.clone()).await;let before:String=sqlx::query_scalar("SELECT xmin::text FROM owner_preferences WHERE key='agent_conversation:primary'").fetch_one(&mut c).await.unwrap();let heartbeat=browser_native(&mut c,"heartbeat_chrome_profile",&context,json!({"profile_commands_enabled":true})).await.unwrap();assert_eq!(heartbeat["ok"],true);let after:String=sqlx::query_scalar("SELECT xmin::text FROM owner_preferences WHERE key='agent_conversation:primary'").fetch_one(&mut c).await.unwrap();assert_ne!(after,before);assert_eq!(browser_pref(&mut c,"agent_conversation:primary").await,memory);execution_seed_policy(&mut c).await;execution_control(&mut c,162,"stop").await.unwrap();let controlled:String=sqlx::query_scalar("SELECT xmin::text FROM owner_preferences WHERE key='agent_conversation:primary'").fetch_one(&mut c).await.unwrap();assert_ne!(controlled,after);assert_eq!(browser_pref(&mut c,"agent_conversation:primary").await,memory);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn dropped_owner_fence_ack_denies_native_and_queue_changes_without_partial_state(){
    let(mut c,context,_)=browser_command_fixture().await;execution_seed_policy(&mut c).await;let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_owner_fence_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.key='agent_conversation:primary' THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_owner_fence_drop BEFORE UPDATE ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_owner_fence_drop()").execute(&mut c).await.unwrap();assert_eq!(browser_native(&mut c,"heartbeat_chrome_profile",&context,json!({"profile_commands_enabled":true})).await.unwrap_err(),Failure("browser_profile_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(execution_control(&mut c,162,"stop").await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_owner_fence_drop ON owner_preferences;DROP FUNCTION fixture_owner_fence_drop()").execute(&mut c).await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn native_health_and_capability_reads_ping_database_without_waiting_or_advancing_owner_fence(){
    let(mut c,context,_)=browser_command_fixture().await;let before:String=sqlx::query_scalar("SELECT xmin::text FROM owner_preferences WHERE key='agent_conversation:primary'").fetch_one(&mut c).await.unwrap();let mut owner=connection().await;let mut held=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *held).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();let health=browser_native(&mut c,"health",&context,json!({})).await.unwrap();assert_eq!(health["ok"],true);let capabilities=browser_native(&mut c,"get_agent_capabilities",&context,json!({})).await.unwrap();assert_eq!(capabilities["ok"],true);assert_eq!(capabilities["data"]["submissions"],false);assert_eq!(sqlx::query_scalar::<_,String>("SELECT xmin::text FROM owner_preferences WHERE key='agent_conversation:primary'").fetch_one(&mut c).await.unwrap(),before);held.rollback().await.unwrap();
}
